 if(o===16){if(v&1){this.reset();return true;}if(v&16){this.rx=[];this.payload=[];}if(v&32){const i=v>>>6&31;if(i===16)for(const e of this.ins)e.fifo=[];else if(this.ins[i])this.ins[i].fifo=[];}return true;}
